mapper.select:
select distinct tt.task_id, tt.user_id, tt.task_title, tt.description, tt.completed, tt.completion_time, tt.urgency_level, tt.start_time, tt.due_date, tt.create_by, tt.create_time, tt.update_by, tt.update_time, tt.deleted, t.tag_name from todo_task tt
left join todo_task_tag ttt on ttt.task_id = tt.task_id
left join todo_tag t on t.tag_id = ttt.tag_id

    tt.user_id = #{userId} and tt.deleted = 0
    and tt.due_date between #{startTime} and #{dueDate}

        and tt.completed = #{completed}


        and tt.parent_id = #{parentId}


order by tt.due_date asc

select parent_task_id as parentTaskId, count(*) as total, sum(case when completed = 1 then 1 else 0 end) as completed from xy_task
#{id}
and deleted = 0 group by parent_id

select distinct tt.task_id, tt.user_id, tt.task_title, tt.description, tt.completed, tt.completion_time, tt.urgency_level, tt.start_time, tt.due_date, tt.create_by, tt.create_time, tt.update_by, tt.update_time, tt.deleted, t.tag_name from todo_task tt left join todo_task_tag ttt on ttt.task_id = tt.task_id left join todo_tag t on t.tag_id = ttt.tag_id
tt.deleted = 0
and tt.task_title like concat('%', #{task.taskTitle}, '%')
and tt.user_id = #{task.userId}
and tt.completed = #{task.completed}
and tt.urgency_level = #{task.urgencyLevel}
order by tt.create_time desc

select count(distinct tt.task_id)
from todo_task tt

    tt.deleted = 0

        and tt.task_title like concat('%', #{task.taskTitle}, '%')


        and tt.user_id = #{task.userId}


        and tt.completed = #{task.completed}


        and tt.urgency_level = #{task.urgencyLevel}

mapper.update:
update todo_task
task_title = #{task.taskTitle}, description = #{task.description}, completed = #{task.completed}, urgency_level = #{task.urgencyLevel}, start_time = #{task.startTime}, due_date = #{task.dueDate}, update_by = #{task.updateBy}, update_time = #{task.updateTime},
where task_id = #{task.taskId}
